// The phrase bank (web3d/words.json, generated by tools/phrases.py): its
// structure, the kindness rule, lengths, sources and the personas it weights.
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import fs from "node:fs";
import test from "node:test";
import { fileURLToPath } from "node:url";

const root = (p) => fileURLToPath(new URL(`../../${p}`, import.meta.url));
const words = JSON.parse(fs.readFileSync(root("web3d/words.json"), "utf8"));
const lines = Object.entries(words.groups).flatMap(([group, g]) => g.lines.map((line) => ({ group, ...line })));

export const REQUIRED = [
  "start", "cut_you_high", "cut_them_high", "deal_them", "deal_you", "seven_them", "seven_you",
  "play_them_brisque", "play_them_trump", "play_them_high", "play_them_low",
  "play_you_brisque", "play_you_trump", "play_you_high", "play_you_low",
  "trick_them", "trick_you", "trick_rich_them", "trick_rich_you", "streak_you", "streak_them",
  "decl_them", "decl_you_marriage", "decl_you_royal", "decl_you_sequence", "decl_you_bezique", "decl_you_double", "decl_you_four",
  "dix_them", "dix_you", "stock_low", "stock_out", "stock_last_you", "stock_last_them", "last_eight",
  "last_trick_you", "last_trick_them", "hand_ahead_them", "hand_ahead_you", "hand_level",
  "double_you_threatened", "double_them_threatened", "double_off_you", "double_off_them",
  "win_you", "win_you_double", "win_them", "win_them_double", "undo",
];

test("every moment of the table has a group of at least one line", () => {
  for (const id of REQUIRED) assert.ok(words.groups[id]?.lines.length >= 1, id);
});

test("groups, kinds and modes are well formed", () => {
  for (const [id, g] of Object.entries(words.groups)) {
    assert.ok(["call", "remark", "chatter"].includes(g.kind), `${id} kind`);
    assert.ok(g.moment, `${id} moment`);
  }
  for (const mode of ["quiet", "normal", "chatty"]) {
    for (const kind of ["call", "remark", "chatter"]) {
      const p = words.modes[mode][kind];
      assert.ok(p >= 0 && p <= 1, `${mode}.${kind}`);
    }
  }
  assert.equal(words.modes.quiet.remark, 0);
  assert.ok(words.modes[words.default_mode]);
});

test("no duplicate lines", () => {
  const seen = new Set();
  for (const l of lines) {
    const key = l.t.toLowerCase();
    assert.ok(!seen.has(key), `duplicate: ${l.t}`);
    seen.add(key);
  }
});

test("lines are short enough to read at a glance", () => {
  for (const l of lines) assert.ok(l.t.length <= 100, `${l.t.length}: ${l.t}`);
});

test("every line has a known source, and a cited line has a locator or a document", () => {
  for (const l of lines) {
    assert.ok(words.sources[l.s], `${l.group}: unknown source ${l.s}`);
    if (l.s === "F97") assert.ok(l.l, `${l.t}: Foster needs a page`);
  }
});

test("interpretation is kept few", () => {
  const own = lines.filter((l) => l.s === "T").length;
  assert.ok(own / lines.length <= 0.3, `${own} of ${lines.length} lines are interpretation`);
});

test("slots are known, and {formula} belongs to the declaring call alone", () => {
  for (const l of lines) {
    for (const [, slot] of l.t.matchAll(/\{(\w+)\}/g)) assert.ok(["formula", "points", "gap"].includes(slot), `${l.t}: ${slot}`);
    if (l.t.includes("{formula}")) assert.equal(l.group, "decl_them");
  }
});

// The kindness rule: luck, speed, the score and the run of the cards are fair
// game; never looks, intelligence, age, gender, class, religion, nationality.
const UNKIND = [
  "stupid", "dumb", "idiot", "fool", "foolish", "silly", "clever", "smart", "brilliant", "genius", "slow-witted", "beginner", "novice", "amateur", "poor",
  "ugly", "fat", "thin", "handsome", "pretty", "beautiful", "old", "young", "elderly", "child", "boy", "girl", "lady", "ladies", "gentleman", "gentlemen",
  "sir", "madam", "man", "men", "woman", "women", "he", "she", "his", "hers", "peasant", "rich", "gypsy", "jew", "jewish", "christian", "catholic",
  "protestant", "english", "french", "german", "american", "swedish", "irish", "scotch", "dutch", "turkish",
];
test("the kindness rule: no word of the unkind list", () => {
  for (const l of lines) {
    const found = (l.t.toLowerCase().match(/[a-z-]+/g) ?? []).filter((w) => UNKIND.includes(w));
    assert.deepEqual(found, [], l.t);
  }
});

test("the personas are the engine's, and weight only groups that exist", () => {
  const rust = fs.readFileSync(root("crates/bezique-core/src/opponent.rs"), "utf8");
  const keys = [...rust.matchAll(/key: "(\w+)"/g)].map((m) => m[1]);
  assert.ok(keys.length >= 4);
  assert.deepEqual(Object.keys(words.personas).sort(), [...keys].sort());
  for (const weights of Object.values(words.personas)) {
    for (const [group, w] of Object.entries(weights)) {
      assert.ok(words.groups[group], group);
      assert.notEqual(words.groups[group].kind, "call", `${group}: calls are not weighted`);
      assert.ok(w > 0 && w <= 2);
    }
  }
});

test("the committed bank is what tools/phrases.py makes", () => {
  execFileSync("python3", [root("tools/phrases.py"), "--check"]);
});
